@namespace sv_a811c1c652724cc0bc66bf7aefd81d5e.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var cssClass = GetStepClass(step);
            <li class="step-item @cssClass">
                @if (step < CurrentStep)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(step == CurrentStep ? "step" : null)">
                        <span class="step-icon">@(step + 1)</span>
                        <span class="step-label">@StepNames[step]</span>
                    </span>
                }
            </li>
            @if (step < StepNames.Length - 1)
            {
                <li class="step-connector @(step < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
