                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? ValidationError;

    private void UpdateReference(int index, Reference reference)
    {
        var updated = new List<Reference>(References);
        updated[index] = reference;
        ReferencesChanged.InvokeAsync(updated);
    }

    private void RemoveReference(int index)
    {
        var updated = new List<Reference>(References);
        updated.RemoveAt(index);
        ReferencesChanged.InvokeAsync(updated);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var updated = new List<Reference>(References)
        {
            new(string.Empty, string.Empty, string.Empty, string.Empty)
        };
        ReferencesChanged.InvokeAsync(updated);
    }

    private void HandleNext()
    {
        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }
        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ValidationError = "Please fill in name and email for all references.";
            return;
        }
        ValidationError = null;
        OnNext.InvokeAsync();
    }
}

