@namespace sv_a811c1c652724cc0bc66bf7aefd81d5e.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-entry">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <small>@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")</small>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="OnSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
}

arguments.file_text:
@page "/apply"
@namespace sv_a811c1c652724cc0bc66bf7aefd81d5e.Components.Pages.Apply
@using sv_a811c1c652724cc0bc66bf7aefd81d5e.Models
@using sv_a811c1c652724cc0bc66bf7aefd81d5e.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              EmailError="@emailError" ValidationError="@validationError"
                              FullNameChanged="v => { fullName = v; StateHasChanged(); }"
                              EmailChanged="v => { email = v; emailError = null; StateHasChanged(); }"
                              PhoneChanged="v => { phone = v; StateHasChanged(); }"
                              AddressChanged="v => { address = v; StateHasChanged(); }"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             EntriesChanged="v => { workEntries = v; StateHasChanged(); }"
                             OnBack="() => GoToStep(0)"
                             OnNext="() => GoToStep(2)" />
            break;

        case 2:
            <ReferencesStep References="references"
                            ReferencesChanged="v => { references = v; StateHasChanged(); }"
                            OnBack="() => GoToStep(1)"
                            OnNext="() => GoToStep(3)" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="v => { coverLetter = v; StateHasChanged(); }"
                             OnBack="() => GoToStep(2)"
                             OnNext="() => GoToStep(4)" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()" WorkEntries="workEntries"
                        References="references" CoverLetter="@coverLetter"
                        IsSubmitting="isSubmitting" IsSubmitted="isSubmitted"
                        ApplicationId="applicationId" ErrorMessage="@submitError"
                        OnBack="() => GoToStep(3)"
                        OnSubmit="HandleSubmit"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;
    private string? emailError;
    private string? validationError;
    private List<WorkEntry> workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> references = new()
    {
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string coverLetter = string.Empty;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        validationError = null;
        currentStep = step;
    }

    private async Task HandlePersonalNext()
    {
        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            validationError = "Please fill in all required fields.";
            return;
        }

        var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
        if (!isValidEmail)
        {
            emailError = "Please enter a valid email address.";
            validationError = null;
            return;
        }

        emailError = null;
        validationError = null;
        currentStep = 1;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(workEntries),
                references,
                coverLetter
            );
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
