@page "/apply"
@namespace sv_a811c1c652724cc0bc66bf7aefd81d5e.Components.Pages.Apply
@using sv_a811c1c652724cc0bc66bf7aefd81d5e.Models
@using sv_a811c1c652724cc0bc66bf7aefd81d5e.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              EmailError="@emailError" ValidationError="@validationError"
                              FullNameChanged="v => { fullName = v; StateHasChanged(); }"
                              EmailChanged="v => { email = v; emailError = null; StateHasChanged(); }"
                              PhoneChanged="v => { phone = v; StateHasChanged(); }"
                              AddressChanged="v => { address = v; StateHasChanged(); }"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             EntriesChanged="v => { workEntries = v; StateHasChanged(); }"
                             OnBack="() => GoToStep(0)"
                             OnNext="() => GoToStep(2)" />
            break;

        case 2:
            <ReferencesStep References="references"
                            ReferencesChanged="v => { references = v; StateHasChanged(); }"
                            OnBack="() => GoToStep(1)"
                            OnNext="() => GoToStep(3)" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="v => { coverLetter = v; StateHasChanged(); }"
                             OnBack="() => GoToStep(2)"
                             OnNext="() => GoToStep(4)" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()" WorkEntries="workEntries"
                        References="references" CoverLetter="@coverLetter"
                        IsSubmitting="isSubmitting" IsSubmitted="isSubmitted"
                        ApplicationId="applicationId" ErrorMessage="@submitError"
                        OnBack="() => GoToStep(3)"
                        OnSubmit="HandleSubmit"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;
    private string? emailError;
    private string? validationError;
    private List<WorkEntry> workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> references = new()
    {
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string coverLetter = string.Empty;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        validationError = null;
        currentStep = step;
    }

    private async Task HandlePersonalNext()
    {
        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            validationError = "Please fill in all required fields.";
            return;
        }

        var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
        if (!isValidEmail)
        {
            emailError = "Please enter a valid email address.";
            validationError = null;
            return;
        }

        emailError = null;
        validationError = null;
        currentStep = 1;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(workEntries),
                references,
                coverLetter
            );
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);
}

