.review-section dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    margin: 0.75rem 0;
    padding: 0.5rem 0;
}

.cover-letter-preview {
